-- Tax residence table, forty-fifth table off Lift Mapper. mCustomerId is a
-- MappedLongForeignKey(this, MappedCustomer) - it stores the customer's internal BIGINT primary
-- key (mappedcustomer.id), not the customer's UUID customerId. mTaxResidenceId is a MappedUUID
-- (36 chars); mDomain/mTaxNumber are MediumString (20 chars each). createdat/updatedat come from
-- the CreatedUpdated mixin.
--
-- Two indexes: a plain index on mcustomerid (auto-generated by the foreign-key field) and a
-- UNIQUE INDEX on (mcustomerid, mdomain, mtaxnumber), matching the entity's own dbIndexes
-- (UniqueIndex(mCustomerId, mDomain, mTaxNumber)), confirmed against a booted instance's
-- information_schema.indexes - a customer cannot have the same domain+number pair twice.

CREATE TABLE "PUBLIC"."MAPPEDTAXRESIDENCE"(
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "UPDATEDAT" TIMESTAMP,
    "CREATEDAT" TIMESTAMP,
    "MCUSTOMERID" BIGINT,
    "MTAXRESIDENCEID" CHARACTER VARYING(36),
    "MDOMAIN" CHARACTER VARYING(20),
    "MTAXNUMBER" CHARACTER VARYING(20)
);
ALTER TABLE "PUBLIC"."MAPPEDTAXRESIDENCE" ADD CONSTRAINT "PUBLIC"."MAPPEDTAXRESIDENCE_PK" PRIMARY KEY("ID");
CREATE INDEX "PUBLIC"."MAPPEDTAXRESIDENCE_MCUSTOMERID" ON "PUBLIC"."MAPPEDTAXRESIDENCE"("MCUSTOMERID" NULLS FIRST);
CREATE UNIQUE INDEX "PUBLIC"."MAPPEDTAXRESIDENCE_MCUSTOMERID_MDOMAIN_MTAXNUMBER" ON "PUBLIC"."MAPPEDTAXRESIDENCE"("MCUSTOMERID" NULLS FIRST, "MDOMAIN" NULLS FIRST, "MTAXNUMBER" NULLS FIRST);
